#!/usr/bin/env python3
"""Sanitize a task repository in-place so no post-task VCS history remains."""

from __future__ import annotations

import json
import os
import shutil
import stat
import subprocess
import sys
from typing import Iterable


def _ensure_writable(path: str) -> None:
    try:
        st = os.lstat(path)
        if not stat.S_ISLNK(st.st_mode):
            mode = st.st_mode
            if stat.S_ISDIR(mode):
                os.chmod(path, mode | stat.S_IRWXU)
            else:
                os.chmod(path, mode | stat.S_IWUSR | stat.S_IRUSR)
    except OSError:
        pass


def _rmtree(path: str) -> None:
    if not os.path.lexists(path):
        return
    if os.path.islink(path) or os.path.isfile(path):
        _unlink(path)
        return

    def onerror(func, p, exc_info):
        _ensure_writable(os.path.dirname(p))
        _ensure_writable(p)
        try:
            func(p)
        except OSError:
            pass

    _ensure_writable(path)
    shutil.rmtree(path, onerror=onerror)


def _unlink(path: str) -> None:
    if not os.path.lexists(path):
        return
    try:
        os.unlink(path)
    except PermissionError:
        _ensure_writable(os.path.dirname(path))
        _ensure_writable(path)
        try:
            os.unlink(path)
        except OSError:
            pass
    except OSError:
        pass


def _make_git_dirs_writable(git_dir: str) -> None:
    _ensure_writable(git_dir)
    for root, dirs, _ in os.walk(git_dir):
        _ensure_writable(root)
        for d in dirs:
            _ensure_writable(os.path.join(root, d))


def _run_git(
    repo_dir: str,
    *args: str,
    check: bool = True,
    input_data: str | None = None,
) -> subprocess.CompletedProcess[str]:
    env = os.environ.copy()
    env["GIT_TERMINAL_PROMPT"] = "0"
    env["GIT_ASKPASS"] = "true"
    cmd = [
        "git",
        "--no-replace-objects",
        "-c",
        "safe.directory=*",
        "-c",
        "core.hooksPath=/dev/null",
        "-C",
        repo_dir,
        *args,
    ]
    return subprocess.run(
        cmd,
        input=input_data,
        capture_output=True,
        text=True,
        check=check,
        env=env,
    )


def _resolve_git_dir(repo_dir: str) -> str:
    res = _run_git(repo_dir, "rev-parse", "--git-dir", check=False)
    if res.returncode != 0:
        raise RuntimeError(f"Not a git repository: {repo_dir}: {res.stderr}")
    gdir = res.stdout.strip()
    if not os.path.isabs(gdir):
        gdir = os.path.abspath(os.path.join(repo_dir, gdir))
    return gdir


def _is_builder_setup_commit(
    repo_dir: str,
    git_dir: str,
    bc: str,
    head_sha: str,
    anc_of_bc: set[str],
) -> bool:
    """Return True if head_sha is an image-builder setup commit on top of bc."""
    if head_sha == bc:
        return True
    head_anc = set(_run_git(repo_dir, "rev-list", head_sha).stdout.splitlines())
    if bc not in head_anc:
        return False

    commits_after_bc = _run_git(
        repo_dir, "rev-list", f"{bc}..{head_sha}"
    ).stdout.splitlines()
    if not commits_after_bc or len(commits_after_bc) > 5:
        return False

    # Check if any commit in bc..head_sha has builder metadata (e.g. SWE-bench)
    builder_markers = (
        "swe-bench",
        "swebench",
        "setup@swebench",
        "buildkitsandbox",
        "r2e-gym",
        "r2egym",
        "swe-gym",
        "swegym",
        "harbor",
    )
    all_have_marker = True
    for c in commits_after_bc:
        meta = _run_git(
            repo_dir, "show", "-s", "--format=%an %ae %cn %ce %B", c
        ).stdout.lower()
        if not any(m in meta for m in builder_markers):
            all_have_marker = False
            break
    if all_have_marker:
        return True

    # Check if ORIG_HEAD exists and points to a different branch tip not containing head_sha
    orig_head_path = os.path.join(git_dir, "ORIG_HEAD")
    if os.path.isfile(orig_head_path):
        try:
            orig_sha = open(orig_head_path, errors="replace").read().strip()
        except OSError:
            orig_sha = ""
        if orig_sha and orig_sha != head_sha:
            cat = _run_git(repo_dir, "cat-file", "-t", orig_sha, check=False)
            if cat.returncode == 0 and cat.stdout.strip() == "commit":
                orig_anc = set(
                    _run_git(repo_dir, "rev-list", orig_sha).stdout.splitlines()
                )
                if head_sha not in orig_anc:
                    return True

    # Check if HEAD reflog shows a reset/checkout to base_commit followed by local commits
    head_log_path = os.path.join(git_dir, "logs", "HEAD")
    if os.path.isfile(head_log_path):
        try:
            log_lines = open(head_log_path, errors="replace").read().splitlines()
        except OSError:
            log_lines = []
        saw_bc = False
        valid_after_bc = True
        for line in log_lines:
            parts = line.split("\t", 1)
            shas = parts[0].split()
            msg = parts[1] if len(parts) > 1 else ""
            if len(shas) >= 2 and shas[1] == bc:
                saw_bc = True
                valid_after_bc = True
            elif saw_bc:
                if not msg.startswith("commit:"):
                    valid_after_bc = False
        if saw_bc and valid_after_bc:
            return True

    return False


def _get_default_abbrev(repo_dir: str) -> tuple[str | None, int, int]:
    cfg = _run_git(repo_dir, "config", "--local", "--get", "core.abbrev", check=False)
    explicit = cfg.stdout.strip() if cfg.returncode == 0 else None
    shas = _run_git(
        repo_dir, "rev-list", "--abbrev-commit", "-n", "25", "HEAD"
    ).stdout.splitlines()
    min_abbrev = min((len(s) for s in shas), default=7)
    head_short = len(_run_git(repo_dir, "rev-parse", "--short", "HEAD").stdout.strip())
    return explicit, min_abbrev, head_short


def _clean_git_config(repo_dir: str, git_dir: str) -> None:
    remotes = _run_git(repo_dir, "remote", check=False).stdout.splitlines()
    for r in remotes:
        r = r.strip()
        if r:
            _run_git(repo_dir, "remote", "remove", r, check=False)

    cfg_file = os.path.join(git_dir, "config")
    if not os.path.isfile(cfg_file):
        return

    res = _run_git(
        repo_dir,
        "config",
        "--file",
        cfg_file,
        "--name-only",
        "--get-regexp",
        r"^(remote|branch|submodule)\.",
        check=False,
    )
    sections_to_remove: set[str] = set()
    for line in res.stdout.splitlines():
        key = line.strip()
        if not key:
            continue
        parts = key.split(".")
        if len(parts) >= 3 and parts[0] in ("remote", "branch"):
            sec = ".".join(parts[:-1])
            sections_to_remove.add(sec)

    for sec in sorted(sections_to_remove):
        _run_git(
            repo_dir,
            "config",
            "--file",
            cfg_file,
            "--remove-section",
            sec,
            check=False,
        )


def _clean_dangling_refs_on_disk(git_dir: str, keep_head_sym: str) -> None:
    refs_dir = os.path.join(git_dir, "refs")
    if not os.path.isdir(refs_dir):
        return

    for entry in os.listdir(refs_dir):
        full = os.path.join(refs_dir, entry)
        if entry not in ("heads", "tags"):
            _rmtree(full)

    # Walk heads and tags and remove any dangling symrefs or unwanted heads
    heads_dir = os.path.join(refs_dir, "heads")
    if os.path.isdir(heads_dir):
        for root, dirs, files in os.walk(heads_dir, topdown=False):
            for f in files:
                p = os.path.join(root, f)
                rel = "refs/" + os.path.relpath(p, refs_dir).replace(os.sep, "/")
                if rel != keep_head_sym:
                    _unlink(p)
            for d in dirs:
                dp = os.path.join(root, d)
                try:
                    if not os.listdir(dp):
                        os.rmdir(dp)
                except OSError:
                    pass

    tags_dir = os.path.join(refs_dir, "tags")
    if os.path.isdir(tags_dir):
        for root, dirs, files in os.walk(tags_dir, topdown=False):
            for d in dirs:
                dp = os.path.join(root, d)
                try:
                    if not os.listdir(dp):
                        os.rmdir(dp)
                except OSError:
                    pass


def _clean_aux_git_files(git_dir: str) -> None:
    # Directories inside .git that may hold history/state
    for dname in (
        "logs",
        "worktrees",
        "rr-cache",
        "rebase-merge",
        "rebase-apply",
        "sequencer",
        "objects/info/commit-graphs",
    ):
        _rmtree(os.path.join(git_dir, dname))

    # Empty legacy branches dir
    branches_dir = os.path.join(git_dir, "branches")
    if os.path.isdir(branches_dir):
        for entry in os.listdir(branches_dir):
            _rmtree(os.path.join(branches_dir, entry))

    # Remove non-sample hooks if any exist
    hooks_dir = os.path.join(git_dir, "hooks")
    if os.path.isdir(hooks_dir):
        for entry in os.listdir(hooks_dir):
            if not entry.endswith(".sample"):
                _rmtree(os.path.join(hooks_dir, entry))

    # Clean info/ directory (keep only exclude and attributes)
    info_dir = os.path.join(git_dir, "info")
    if os.path.isdir(info_dir):
        for entry in os.listdir(info_dir):
            if entry not in ("exclude", "attributes"):
                _rmtree(os.path.join(info_dir, entry))

    # Clean objects/info/
    obj_info_dir = os.path.join(git_dir, "objects", "info")
    if os.path.isdir(obj_info_dir):
        for entry in os.listdir(obj_info_dir):
            _rmtree(os.path.join(obj_info_dir, entry))

    # Clean objects/pack/ auxiliary files (.keep, .promisor, multi-pack-index, .bitmap, .rev, .mtimes)
    pack_dir = os.path.join(git_dir, "objects", "pack")
    if os.path.isdir(pack_dir):
        for entry in os.listdir(pack_dir):
            if entry == "multi-pack-index" or entry.endswith(
                (".keep", ".promisor", ".bitmap", ".rev", ".mtimes")
            ):
                _unlink(os.path.join(pack_dir, entry))

    # Allowed top-level entries in .git
    allowed_top = {
        "HEAD",
        "branches",
        "config",
        "description",
        "hooks",
        "index",
        "info",
        "modules",
        "objects",
        "packed-refs",
        "refs",
        "shallow",
        "commondir",
        "gitdir",
    }
    for entry in os.listdir(git_dir):
        if entry not in allowed_top:
            _rmtree(os.path.join(git_dir, entry))


def sanitize_repo(repo_dir: str, base_commit: str) -> None:
    repo_dir = os.path.abspath(repo_dir)
    git_dir = _resolve_git_dir(repo_dir)
    _make_git_dirs_writable(git_dir)

    # First remove grafts and replace refs so ancestry queries see true graph
    _unlink(os.path.join(git_dir, "info", "grafts"))
    _rmtree(os.path.join(git_dir, "refs", "replace"))
    replace_refs = _run_git(
        repo_dir, "for-each-ref", "--format=%(refname)", "refs/replace", check=False
    ).stdout.splitlines()
    if replace_refs:
        stdin_del = "".join(f"delete {r}\n" for r in replace_refs if r.strip())
        _run_git(repo_dir, "update-ref", "--stdin", input_data=stdin_del, check=False)

    # Verify base_commit resolves to a commit
    bc_res = _run_git(repo_dir, "rev-parse", "--verify", f"{base_commit}^{{commit}}")
    bc = bc_res.stdout.strip()

    explicit_abbrev, orig_min_abbrev, orig_head_short = _get_default_abbrev(repo_dir)

    anc_of_bc = set(_run_git(repo_dir, "rev-list", bc).stdout.splitlines())
    head_sha = _run_git(repo_dir, "rev-parse", "--verify", "HEAD^{commit}").stdout.strip()

    if head_sha != bc:
        if not _is_builder_setup_commit(repo_dir, git_dir, bc, head_sha, anc_of_bc):
            _run_git(repo_dir, "reset", "--hard", bc)
            head_sha = bc

    head_anc = set(_run_git(repo_dir, "rev-list", "HEAD").stdout.splitlines())
    allowed_commits = anc_of_bc | head_anc

    head_sym_res = _run_git(repo_dir, "symbolic-ref", "-q", "HEAD", check=False)
    head_sym = head_sym_res.stdout.strip() if head_sym_res.returncode == 0 else ""

    # Enumerate all refs and delete everything except:
    # 1. head_sym (if HEAD is symbolic)
    # 2. refs/tags/* whose peeled object is a commit in anc_of_bc
    refs_out = _run_git(
        repo_dir,
        "for-each-ref",
        "--format=%(refname) %(objecttype) %(objectname) %(*objecttype) %(*objectname)",
    ).stdout.splitlines()

    to_delete: list[str] = []
    for line in refs_out:
        parts = line.split()
        if len(parts) < 3:
            continue
        refname, otype, obj = parts[0], parts[1], parts[2]
        if head_sym and refname == head_sym:
            continue
        if refname.startswith("refs/tags/"):
            if otype == "commit":
                target_commit = obj
            elif otype == "tag" and len(parts) >= 5 and parts[3] == "commit":
                target_commit = parts[4]
            else:
                target_commit = None
            if target_commit and target_commit in anc_of_bc:
                continue
        to_delete.append(refname)

    if to_delete:
        stdin_data = "".join(f"delete {r}\n" for r in to_delete)
        _run_git(repo_dir, "update-ref", "--stdin", input_data=stdin_data)

    # Clean config (remotes, tracking branches)
    _clean_git_config(repo_dir, git_dir)

    # Clean dangling refs on disk and repack refs
    _clean_dangling_refs_on_disk(git_dir, head_sym)
    _run_git(repo_dir, "pack-refs", "--all")
    _clean_dangling_refs_on_disk(git_dir, head_sym)

